from pathlib import Path
from shutil import copyfile
import json
import requests

base = "http://127.0.0.1:8000"
payload = {'prompt': 'A small penguin on a sunny island', 'size': 1024, 'seed': 7, 'output': 'result.png'}
response = requests.post(base + '/predict', json=payload, timeout=600)
response.raise_for_status()
result = response.json()

# Python도 같은 NPU 서버에서 실행합니다. 파일은 현재 폴더에 저장합니다.
def save_media(value):
    if isinstance(value, dict):
        for item in value.values():
            save_media(item)
    elif isinstance(value, list):
        for item in value:
            save_media(item)
    elif isinstance(value, str) and len(value) < 4096 and "\n" not in value:
        source = Path(value)
        if source.suffix.lower() in {".png", ".jpg", ".glb", ".obj", ".ply", ".safetensors"} and source.is_file():
            target = Path.cwd() / source.name
            if source.resolve() != target.resolve():
                copyfile(source, target)
            print(target.resolve())

save_media(result)
text = json.dumps(result, ensure_ascii=False, indent=2)
if len(text) > 2000:
    Path("result.json").write_text(text + "\n", encoding="utf-8")
    print(Path("result.json").resolve())
else:
    print(text)

